-- Migration: Ingest official notification posts (Category A dataset)
-- Purpose: Create recruitment records and insert posts from official FreeJobAlert source
-- Date: 2026-10-15
-- Strategy: Create one recruitment per post (recruitment_id required), map organizations to canonical IDs

BEGIN;

-- Stage 1: Create temporary table with official posts data
CREATE TEMP TABLE official_posts_raw (
  official_name TEXT,
  post_title TEXT,
  vacancies INTEGER,
  last_date TEXT,
  official_url TEXT
);

-- Stage 2: Bulk insert raw official posts data
;

-- Stage 3: Create recruitment records from official posts with slug generation
WITH official_posts_with_org AS (
  SELECT
    opr.official_name,
    opr.post_title,
    opr.vacancies,
    TO_DATE(opr.last_date, 'DD-MM-YYYY') as deadline,
    opr.official_url,
    COALESCE(om.canonical_org_id, -1) as canonical_org_id
  FROM official_posts_raw opr
  LEFT JOIN organization_mapping om ON opr.official_name = om.official_name
),
created_recruitments AS (
    name,
    organization_id,
    year,
    slug,
    status,
    application_end_date,
    notification_url,
    created_at,
    updated_at
  )
  SELECT
    opwo.post_title,
    opwo.canonical_org_id,
    EXTRACT(YEAR FROM opwo.deadline)::smallint,
    LOWER(
      TRIM(
        REGEXP_REPLACE(
          REGEXP_REPLACE(
            REGEXP_REPLACE(opwo.post_title, '[^a-zA-Z0-9\s-]', '', 'g'),
            '\s+', '-', 'g'
          ),
          '-+', '-', 'g'
        ),
        '-'
      )
    ),
    CASE
      WHEN opwo.deadline > NOW()::DATE THEN 'ACTIVE'::recruitment_status
      ELSE 'CLOSED'::recruitment_status
    END,
    opwo.deadline,
    opwo.official_url,
    NOW(),
    NOW()
  FROM official_posts_with_org opwo
  RETURNING id, name
)

-- Stage 4: Insert posts with recruitment_id references
SELECT
  cr.id,
  6,  -- Default position_id for "Other" category
  cr.name,
  LOWER(
    TRIM(
      REGEXP_REPLACE(
        REGEXP_REPLACE(
          REGEXP_REPLACE(cr.name, '[^a-zA-Z0-9\s-]', '', 'g'),
          '\s+', '-', 'g'
        ),
        '-+', '-', 'g'
      ),
      '-'
    )
  ),
  cr.name,
  (SELECT vacancies FROM official_posts_raw WHERE post_title = cr.name LIMIT 1),
  jsonb_build_object('application_end_date', (SELECT TO_DATE(last_date, 'DD-MM-YYYY') FROM official_posts_raw WHERE post_title = cr.name LIMIT 1)::text),
  (SELECT official_url FROM official_posts_raw WHERE post_title = cr.name LIMIT 1),
  true,
  NOW(),
  NOW()
FROM created_recruitments cr
ON CONFLICT (recruitment_id, LOWER(name)) DO NOTHING;

-- Verification and logging
DO $$
DECLARE
  post_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO post_count FROM posts WHERE is_official_source = true;
  RAISE NOTICE 'Official posts ingested. Total official posts in database: %', post_count;
END $$;

COMMIT;